pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 futureTime) public {
        vm.assume(amount > 0);
        vm.assume(futureTime > block.timestamp);
        address actor = address(0xABCD);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(futureTime);
        (uint256 unlockTime, ) = c.Acc(actor);
        assertTrue(unlockTime > block.timestamp);
    }
}
